SOURCE_HASH = "b06781a26c4469e8f12830a04d455957bf620d42b9e1df155e93ee00f293d1c9"
VERSION = "omniwrap.agent-session/v1"
LIMIT_KEYS = ("turns", "model_calls", "tool_calls", "tokens", "cost", "elapsed_seconds", "concurrency", "input_bytes", "output_bytes")


class Provider(Protocol):
    version: Literal["omniwrap.agent-provider/v1"]
    identity: str

    async def propose(self, context: Mapping[str, Any], remaining: Mapping[str, float]) -> Mapping[str, Any]: ...

    async def aclose(self) -> None: ...


class SessionError(RuntimeError):
    code = "agent_session_refused"
    retryable = False


class InDoubt(SessionError):
    """Reconciliation must attest a known result; this session never retries it."""
    code = "agent_session_in_doubt"


def _bytes(value: Any) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False).encode("utf-8")


def _hash(value: Any) -> str:
    return hashlib.sha256(_bytes(value)).hexdigest()


def _validate(value: Any, schema: Mapping[str, Any], schemas: Mapping[str, Any], depth: int = 0) -> None:
    if schema.get("unsupported"):
        raise SessionError(schema["unsupported"])
    if depth > 64:
        raise SessionError("argument nesting limit")
    if schema.get("ref"):
        reference = schema["ref"]
        prefix = "#/components/schemas/"
        if not isinstance(reference, str) or not reference.startswith(prefix):
            raise SessionError("unresolved argument schema")
        segment = reference[len(prefix):]
        if not segment or "/" in segment or re.search(r"~(?![01])", segment):
            raise SessionError("unresolved argument schema")
        ref = segment.replace("~1", "/").replace("~0", "~")
        if ref not in schemas:
            raise SessionError("unresolved argument schema")
        _validate(value, schemas[ref], schemas, depth + 1)
    kind = schema.get("type")
    if value is None and schema.get("nullable"):
        return
    checks = {"string": lambda: type(value) is str, "integer": lambda: type(value) is int and abs(value) <= 9007199254740991, "number": lambda: type(value) in (int, float) and math.isfinite(value), "boolean": lambda: type(value) is bool, "object": lambda: type(value) is dict, "array": lambda: type(value) is list, "null": lambda: value is None}
    if kind in checks and not checks[kind]():
        raise SessionError("argument type mismatch")
    if schema.get("enum") and value not in schema["enum"]:
        raise SessionError("argument enum mismatch")
    if type(value) is dict:
        props = schema.get("properties", {})
        if any(key not in value for key in schema.get("required", [])):
            raise SessionError("missing required body property")
        for key, item in value.items():
            if key in props:
                _validate(item, props[key], schemas, depth + 1)
            elif isinstance(schema.get("additional_properties"), dict):
                _validate(item, schema["additional_properties"], schemas, depth + 1)
            elif schema.get("additional_properties") is False:
                raise SessionError("unknown body property")
    if type(value) is list and schema.get("items"):
        for item in value:
            _validate(item, schema["items"], schemas, depth + 1)
    if "const" in schema and value != schema["const"]:
        raise SessionError("argument const mismatch")
    constraints = schema.get("constraints", {})
    for name, operator in (("minimum", lambda a,b:a >= b), ("maximum", lambda a,b:a <= b), ("exclusiveMinimum", lambda a,b:a > b), ("exclusiveMaximum", lambda a,b:a < b)):
        if name in constraints and type(value) in (int, float) and not operator(value, constraints[name]):
            raise SessionError("argument numeric constraint")
    if "multipleOf" in constraints and type(value) in (int, float) and not math.isclose(value / constraints["multipleOf"], round(value / constraints["multipleOf"])):
        raise SessionError("argument multiple constraint")
    for minimum, maximum, types in (("minLength", "maxLength", (str,)), ("minItems", "maxItems", (list,)), ("minProperties", "maxProperties", (dict,))):
        if type(value) in types and ((minimum in constraints and len(value) < constraints[minimum]) or (maximum in constraints and len(value) > constraints[maximum])):
            raise SessionError("argument size constraint")
    if type(value) is str and "pattern" in constraints and re.search(constraints["pattern"], value) is None:
        raise SessionError("argument pattern mismatch")
    if type(value) is list and constraints.get("uniqueItems") and len({_bytes(item) for item in value}) != len(value):
        raise SessionError("argument uniqueness mismatch")
    for union in ("one_of", "any_of"):
        if schema.get(union):
            count = 0
            for branch in schema[union]:
                try:
                    _validate(value, branch, schemas, depth + 1)
                    count += 1
                except SessionError:
                    pass
            if count == 0 or (union == "one_of" and count != 1):
                raise SessionError("argument union mismatch")
    if schema.get("not"):
        try:
            _validate(value, schema["not"], schemas, depth + 1)
        except SessionError:
            pass
        else:
            raise SessionError("argument forbidden schema")
    for branch in schema.get("all_of", []):
        _validate(value, branch, schemas, depth + 1)


class AtomicCheckpoint:
    def __init__(self, path: Path, key: bytes):
        if type(key) is not bytes or len(key) < 32:
            raise SessionError("checkpoint key requires at least 32 bytes")
        self.path, self.key = Path(path), key
        self.revision = None

    def load(self) -> Dict[str, Any] | None:
        if not self.path.exists():
            return None
        payload = self.path.read_bytes()
        self.revision = hashlib.sha256(payload).hexdigest()
        document = json.loads(payload)
        if set(document) != {"state", "mac"} or not hmac.compare_digest(document["mac"], hmac.new(self.key, _bytes(document["state"]), hashlib.sha256).hexdigest()):
            raise SessionError("checkpoint authentication failed")
        return document["state"]

    def save(self, state: Mapping[str, Any]) -> None:
        payload = _bytes({"state": state, "mac": hmac.new(self.key, _bytes(state), hashlib.sha256).hexdigest()})
        self.path.parent.mkdir(parents=True, exist_ok=True)
        lock = self.path.with_name(self.path.name + ".lock")
        try:
            descriptor = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
        except FileExistsError as exc:
            raise SessionError("checkpoint writer active or abandoned; explicit recovery required") from exc
        name = None
        try:
            os.close(descriptor)
            observed = hashlib.sha256(self.path.read_bytes()).hexdigest() if self.path.exists() else None
            if observed != self.revision:
                raise SessionError("checkpoint changed by another session")
            descriptor, name = tempfile.mkstemp(prefix=".agent-", dir=self.path.parent)
            with os.fdopen(descriptor, "wb") as handle:
                handle.write(payload)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(name, self.path)
            self.revision = hashlib.sha256(payload).hexdigest()
        finally:
            if name is not None and os.path.exists(name):
                os.unlink(name)
            os.unlink(lock)


class AgentSession:
    def __init__(self, client: Any, provider: Provider, *, artifact_hash: str, allowed_tools: List[str], limits: Mapping[str, float], checkpoint: AtomicCheckpoint, persist_result: Callable[[str, Any], Any], approve_write: Callable[[str, str], Awaitable[bool]]):
        if set(limits) != set(LIMIT_KEYS) or any(type(value) not in (int, float) or not math.isfinite(value) or value <= 0 for value in limits.values()):
            raise SessionError("all nine positive finite budgets are mandatory")
        for key in ("turns", "model_calls", "tool_calls", "tokens", "concurrency", "input_bytes", "output_bytes"):
            if int(limits[key]) != limits[key] or limits[key] > 9007199254740991:
                raise SessionError("count budgets must be integers")
        if getattr(provider, "version", None) != "omniwrap.agent-provider/v1" or not provider.identity or len(artifact_hash) != 64 or any(c not in "0123456789abcdef" for c in artifact_hash):
            raise SessionError("provider identity and exact archive hash required")
        if type(allowed_tools) is not list or not allowed_tools or any(type(tool) is not str or tool not in REGISTRY for tool in allowed_tools) or len(set(allowed_tools)) != len(allowed_tools):
            raise SessionError("explicit nonempty unique SDK operation allowlist required")
        self.allowed_tools = frozenset(allowed_tools)
        self.client, self.provider, self.checkpoint = client, provider, checkpoint
        self.persist_result, self.approve_write = persist_result, approve_write
        self.schemas = SCHEMAS
        self.binding = {"version": VERSION, "source": SOURCE_HASH, "artifact": artifact_hash, "registry": _hash(REGISTRY), "provider": {"identity": provider.identity, "version": provider.version}, "limits": dict(limits), "allowed_tools": sorted(allowed_tools)}
        self.limits = dict(limits)
        self.state = checkpoint.load() or {"binding": self.binding, "used": {key: 0 for key in LIMIT_KEYS}, "receipts": [], "pending": [], "final": False}
        if self.state["binding"] != self.binding:
            raise SessionError("stale or mixed checkpoint")
        previous = "0" * 64
        seen = set()
        for receipt in self.state["receipts"]:
            body = {key: value for key, value in receipt.items() if key != "hash"}
            if body["previous"] != previous or receipt["hash"] != _hash(body) or body["id"] in seen:
                raise SessionError("corrupt receipt chain")
            previous = receipt["hash"]
            seen.add(body["id"])
        if set(self.state["used"]) != set(LIMIT_KEYS):
            raise SessionError("corrupt budget state")
        for key, value in self.state["used"].items():
            if key not in self.limits or type(value) not in (int, float) or not math.isfinite(value) or value < 0 or value > self.limits[key]:
                raise SessionError("corrupt budget state")
        self.state.setdefault("observed_usage", {"tokens": self.state["used"]["tokens"], "cost": self.state["used"]["cost"]})
        self.running = False

    def _charge(self, key: str, amount: float) -> None:
        if type(amount) not in (int, float) or not math.isfinite(amount) or amount < 0 or self.state["used"][key] + amount > self.limits[key]:
            raise SessionError("budget exceeded: " + key)
        self.state["used"][key] += amount

    def reconcile(self, call_id: str, result: Any) -> None:
        if self.running:
            raise SessionError("cannot reconcile an active session")
        pending = next((item for item in self.state["pending"] if item["id"] == call_id), None)
        if pending is None:
            raise SessionError("unknown in-doubt call")
        self._ack(pending, result)

    def _ack(self, call: Mapping[str, Any], result: Any) -> None:
        safe = self.persist_result(call["tool"], result)
        self._charge("output_bytes", len(_bytes(safe)))
        receipt = {"id": call["id"], "tool": call["tool"], "arguments_hash": call["arguments_hash"], "mutation": call["mutation"], "result": safe, "previous": self.state["receipts"][-1]["hash"] if self.state["receipts"] else "0" * 64}
        receipt["hash"] = _hash(receipt)
        self.state["receipts"].append(receipt)
        self.state["pending"] = [item for item in self.state["pending"] if item["id"] != call["id"]]
        self.checkpoint.save(self.state)

    async def run(self, input: Any) -> Any:
        if self.running:
            raise SessionError("session already running")
        if self.state["pending"]:
            raise InDoubt("explicit reconciliation required; no call will be retried")
        if self.state["final"]:
            return copy.deepcopy(self.state["final_result"])
        self.running = True
        started = time.monotonic()
        self.state.setdefault("deadline", time.time() + self.limits["elapsed_seconds"] - self.state["used"]["elapsed_seconds"])
        remaining_time = min(self.limits["elapsed_seconds"] - self.state["used"]["elapsed_seconds"], self.state["deadline"] - time.time())
        tasks = []
        try:
            self._charge("input_bytes", len(_bytes(input)))
            async def loop():
                while True:
                    self._charge("turns", 1)
                    self._charge("model_calls", 1)
                    self.checkpoint.save(self.state)
                    context = {"input": input, "results": copy.deepcopy(self.state["receipts"]), "tools": copy.deepcopy({tool: REGISTRY[tool] for tool in sorted(self.allowed_tools)}), "version": VERSION}
                    self._charge("input_bytes", len(_bytes(context)))
                    proposal = await self.provider.propose(context, {key: self.limits[key] - self.state["used"][key] for key in LIMIT_KEYS})
                    if type(proposal) is not dict or set(proposal) not in ({"usage", "final"}, {"usage", "calls"}):
                        raise SessionError("malformed proposal")
                    self._charge("input_bytes", len(_bytes(proposal)))
                    if type(proposal["usage"]) is not dict or set(proposal["usage"]) != {"tokens", "cost"}:
                        raise SessionError("provider usage required")
                    for key in ("tokens", "cost"):
                        amount = proposal["usage"][key]
                        if type(amount) not in (int, float) or not math.isfinite(amount) or amount < 0 or (key == "tokens" and int(amount) != amount):
                            raise SessionError("invalid provider usage")
                        self.state["observed_usage"][key] += amount
                    for key in ("tokens", "cost"):
                        self._charge(key, proposal["usage"][key])
                    if "final" in proposal:
                        safe = self.persist_result("$final", proposal["final"])
                        self._charge("output_bytes", len(_bytes(safe)))
                        self.state.update(final=True, final_result=safe)
                        self.checkpoint.save(self.state)
                        return safe
                    calls = proposal["calls"]
                    if type(calls) is not list or not calls or len(calls) > self.limits["concurrency"]:
                        raise SessionError("empty calls or concurrency budget exceeded")
                    seen = {item["id"] for item in self.state["receipts"]}
                    prepared = []
                    for call in calls:
                        if type(call) is not dict or set(call) != {"id", "tool", "arguments"} or type(call["id"]) is not str or not call["id"] or call["id"] in seen or call["tool"] not in self.allowed_tools:
                            raise SessionError("unknown tool, malformed call or duplicate call id")
                        seen.add(call["id"])
                        descriptor = REGISTRY[call["tool"]]
                        if descriptor["execution"] != "buffered-json":
                            raise SessionError("stream/upload operation is not qualified for session execution")
                        args = call["arguments"]
                        allowed = {item["name"] for item in descriptor["arguments"]}
                        if type(args) is not dict or set(args) - allowed:
                            raise SessionError("unknown arguments; request options forbidden")
                        for item in descriptor["arguments"]:
                            if item["required"] and item["name"] not in args:
                                raise SessionError("missing required argument")
                            if item["name"] in args:
                                if item["caller_only"]:
                                    raise SessionError("header/cookie arguments require caller configuration")
                                _validate(args[item["name"]], item["schema"], self.schemas)
                        prepared.append({"id": call["id"], "tool": call["tool"], "arguments_hash": _hash(args), "mutation": descriptor["mutation"]})
                    self._charge("tool_calls", len(calls))
                    for call in prepared:
                        if call["mutation"] and await self.approve_write(call["tool"], call["arguments_hash"]) is not True:
                            raise SessionError("explicit write approval required")
                    self.state["pending"] = prepared
                    self.checkpoint.save(self.state)
                    async def invoke(call):
                        descriptor = REGISTRY[call["tool"]]
                        return await getattr(self.client, descriptor["method"])(**call["arguments"], max_retries=0, max_response_bytes=int(self.limits["output_bytes"] - self.state["used"]["output_bytes"]))
                    tasks[:] = [asyncio.create_task(invoke(call)) for call in calls]
                    results = await asyncio.gather(*tasks)
                    for call, result in zip(prepared, results):
                        self._ack(call, result)
                    tasks.clear()
            return await asyncio.wait_for(loop(), timeout=remaining_time)
        except Exception as exc:
            if any(call["mutation"] for call in self.state["pending"]):
                raise InDoubt("mutation outcome unresolved; reconcile before another session execution") from exc
            raise
        finally:
            for task in tasks:
                if not task.done():
                    task.cancel()
            if tasks:
                await asyncio.gather(*tasks, return_exceptions=True)
            self.state["observed_usage"]["elapsed_seconds"] = self.state["used"]["elapsed_seconds"] + time.monotonic() - started
            self.state["used"]["elapsed_seconds"] = min(self.limits["elapsed_seconds"], self.state["observed_usage"]["elapsed_seconds"])
            try:
                self.checkpoint.save(self.state)
            finally:
                try:
                    await asyncio.wait_for(self.provider.aclose(), timeout=min(1, self.limits["elapsed_seconds"]))
                finally:
                    await self.client.aclose()
                    self.running = False
